import functools
from typing import Tuple, Dict, List

# Memoization cache structure: cache[(state_tuple, player)] -> guaranteed_uncovered_squares
# player: True for Alice (Maximizer), False for Bob (Minimizer)

def solve_game(N: int) -> int:
    """
    Computes U(N) using minimax recursion with memoization.
    State is represented by a sorted tuple of segment lengths.
    """

    @functools.lru_cache(None)
    def minimax(state: Tuple[int, ...], is_alice_turn: bool) -> int:
        # 1. Terminal condition check
        # If no segment is long enough (>= 2), the game ends.
        if not any(l >= 2 for l in state):
            return sum(state)

        # 2. Generate next possible states
        possible_outcomes = []

        for i in range(len(state)):
            L = state[i]

            if L >= 2:

                # Iterate over all possible tile placements j (1-indexed relative to segment start)
                # A tile covers positions j and j+1 (within the L segment)
                for j in range(1, L):

                    # Construct the new list of segments
                    new_segments_list = list(state[:i]) + list(state[i+1:])

                    # Tile placement at j, j+1 splits L into:
                    # Left segment length: j - 1
                    # Right segment length: L - (j + 1) = L - j - 1

                    L_left = j - 1
                    L_right = L - j - 1

                    # Add new segments if they are non-zero
                    if L_left > 0:
                        new_segments_list.append(L_left)
                    if L_right > 0:
                        new_segments_list.append(L_right)

                    # Sort and convert to tuple for the next state
                    new_state = tuple(sorted(new_segments_list))

                    # Recurse for the opponent's turn
                    if is_alice_turn:
                        # Alice maximizes the result from Bob's move
                        outcome = minimax(new_state, False)
                        possible_outcomes.append(outcome)
                    else:
                        # Bob minimizes the result from Alice's move
                        outcome = minimax(new_state, True)
                        possible_outcomes.append(outcome)

        # 3. Determine the best outcome based on whose turn it is
        if not possible_outcomes:
             # This case should ideally be covered by the terminal check, 
             # but handle defensively.
            return sum(state)

        if is_alice_turn:
            return max(possible_outcomes)
        else:
            return min(possible_outcomes)

    # Initial call: State is (N,), Alice starts (True)
    return minimax((N,), True)

